export function createOfflineQueue({
  storage,
  send,
  key = "queue:v1",
  maxAttempts = 5,
}) {
  let items = [];

  try {
    const raw = storage.getItem(key);
    const saved = raw === null ? [] : JSON.parse(raw);
    if (Array.isArray(saved)) {
      items = saved;
    }
  } catch {
    // Unreadable or malformed stored data starts an empty queue.
  }

  let inFlight = null;
  let runningFlush = null;

  function persist() {
    storage.setItem(key, JSON.stringify(items));
  }

  function enqueue(action) {
    if (items.some((item) => item.id === action.id)) {
      return;
    }

    if (action.dedupeKey !== undefined) {
      const match = items.find(
        (item) =>
          item !== inFlight && item.dedupeKey === action.dedupeKey,
      );

      if (match) {
        match.type = action.type;
        match.payload = action.payload;
        match.attempts = 0;
        persist();
        return;
      }
    }

    items.push({
      id: action.id,
      type: action.type,
      payload: action.payload,
      dedupeKey: action.dedupeKey,
      attempts: 0,
    });
    persist();
  }

  function flush() {
    if (runningFlush !== null) {
      return runningFlush;
    }

    let resolveFlush;
    let rejectFlush;

    const promise = new Promise((resolve, reject) => {
      resolveFlush = resolve;
      rejectFlush = reject;
    });

    // Install the shared promise before send can synchronously reenter flush.
    runningFlush = promise;

    void (async () => {
      const sent = [];
      const failed = [];

      try {
        while (items.length > 0) {
          const item = items[0];
          inFlight = item;

          let outcome = "retryable";

          try {
            const result = await send({
              id: item.id,
              type: item.type,
              payload: item.payload,
            });

            if (result && result.ok === true) {
              outcome = "sent";
            } else if (
              result &&
              result.ok === false &&
              result.retryable === false
            ) {
              outcome = "rejected";
            }
          } catch {
            // Rejections and synchronous send errors are retryable.
          }

          inFlight = null;

          if (outcome === "sent") {
            items.shift();
            sent.push(item.id);
            persist();
          } else if (outcome === "rejected") {
            items.shift();
            failed.push({ id: item.id, reason: "rejected" });
            persist();
          } else {
            item.attempts += 1;
            persist();

            if (item.attempts >= maxAttempts) {
              items.shift();
              failed.push({ id: item.id, reason: "max-attempts" });
              persist();
            }

            // Even an exhausted item stops this run.
            break;
          }
        }

        resolveFlush({ sent, failed, remaining: items.length });
      } catch (error) {
        rejectFlush(error);
      } finally {
        inFlight = null;
        runningFlush = null;
      }
    })();

    return promise;
  }

  return {
    enqueue,
    flush,

    size() {
      return items.length;
    },

    peek() {
      return items.map((item) => ({
        id: item.id,
        type: item.type,
        payload: item.payload,
        dedupeKey: item.dedupeKey,
        attempts: item.attempts,
      }));
    },
  };
}
